export function partition(values, predicate) {
  const matches = [];
  const nonMatches = [];

  for (const value of values) {
    if (predicate(value)) {
      matches.push(value);
    } else {
      nonMatches.push(value);
    }
  }

  return [matches, nonMatches];
}

export function bucketize(values, keyFunction) {
  const buckets = new Map();

  for (const value of values) {
    const key = keyFunction(value);

    if (!buckets.has(key)) {
      buckets.set(key, []);
    }

    buckets.get(key).push(value);
  }

  return buckets;
}

