function exitWithParseError(programName, message) {
  process.stderr.write(`usage: ${programName} [-h] --a A\n`);
  process.stderr.write(`${programName}: error: ${message}\n`);
  process.exit(2);
}

export function parseCommandLine(argv, scriptPath) {
  const programName = getProgramName(scriptPath);
  let aValue;
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      exitWithHelp(programName);
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined || next.startsWith('-')) {
        exitWithParseError(programName, 'argument --a: expected one argument');
      }

      aValue = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    unknown.push(token);
  }

  if (aValue === undefined) {
    exitWithParseError(programName, 'the following arguments are required: --a');
  }

  if (unknown.length > 0) {
    exitWithParseError(programName, `unrecognized arguments: ${unknown.join(' ')}`);
  }

  return { a: aValue };
}

